-- Generated from PF2e 8.6.1 pack headers. Descriptions are not stored.
BEGIN;
ALTER TABLE pf2e_catalog_entries ADD COLUMN IF NOT EXISTS foundry_document_id text;
ALTER TABLE pf2e_catalog_entries ADD COLUMN IF NOT EXISTS source_url text;
ALTER TABLE pf2e_catalog_entries ADD COLUMN IF NOT EXISTS rarity text;
ALTER TABLE pf2e_catalog_entries ADD COLUMN IF NOT EXISTS traditions text;
ALTER TABLE pf2e_catalog_entries ADD COLUMN IF NOT EXISTS pack_label text;
ALTER TABLE pf2e_catalog_entries DROP CONSTRAINT IF EXISTS pf2e_catalog_entries_item_kind_check;
ALTER TABLE pf2e_catalog_entries ADD CONSTRAINT pf2e_catalog_entries_item_kind_check CHECK (item_kind = ANY (ARRAY['action','adventureaction','ancestry','ancestryfeature','army','background','boon','campaignFeature','character','class','classfeature','condition','deity','effect','equipment','familiar','familiarability','feat','hazard','heritage','npc','spell','vehicle']));
CREATE INDEX IF NOT EXISTS idx_pf2e_catalog_entries_document ON pf2e_catalog_entries (foundry_document_id);
CREATE TEMP TABLE _doc (item_kind text, foundry_type text, pf2e_name text, pf2e_slug text, compendium_collection text, source_path text, category text, traits text, level integer, pf2e_source_book text, foundry_document_id text, source_url text, rarity text, traditions text, pack_label text) ON COMMIT DROP;

UPDATE pf2e_catalog_entries e SET foundry_document_id=d.foundry_document_id, source_url=d.source_url, rarity=d.rarity, traditions=NULLIF(d.traditions,''), pack_label=d.pack_label FROM _doc d WHERE e.source_path=d.source_path;
SELECT 'pf2e-remaster',d.item_kind,d.foundry_type,d.pf2e_name,d.pf2e_slug,d.compendium_collection,d.source_path,d.category,NULLIF(d.traits,''),d.level,d.pf2e_source_book,d.foundry_document_id,d.source_url,d.rarity,NULLIF(d.traditions,''),d.pack_label FROM _doc d WHERE NOT EXISTS (SELECT 1 FROM pf2e_catalog_entries e WHERE e.source_path=d.source_path);
COMMIT;
